using System;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class DeepTideColossusInstaller
{
 [MenuItem("Tools/Before We Fight/Install DeepTide Colossi")]
 public static void Install(){var f=Import("Assets/Art/Imported/Enemies/deeptide_colossus_animated.png",39,48,48,"DeepTideColossus",48);var v=Import("Assets/Art/Imported/Enemies/deeptide_colossus_vfx.png",8,64,40,"DeepTideVfx",32);var prefab=Build(f,v);var scene=EditorSceneManager.OpenScene("Assets/Scenes/Arena.unity",OpenSceneMode.Single);foreach(var g in scene.GetRootGameObjects().Where(x=>x.name.StartsWith("DeepTide Colossus ")).ToArray())UnityEngine.Object.DestroyImmediate(g);Vector2[] p={new(12,11),new(-12,-10)};for(int i=0;i<p.Length;i++){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.name=$"DeepTide Colossus {i+1:00}";go.transform.position=p[i];}EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("DeepTide Colossi installed in Arena.");}
 static Sprite[] Import(string path,int count,int width,int height,string prefix,float ppu){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var im=(TextureImporter)AssetImporter.GetAtPath(path);im.textureType=TextureImporterType.Sprite;im.spriteImportMode=SpriteImportMode.Multiple;im.spritePixelsPerUnit=ppu;im.filterMode=FilterMode.Point;im.textureCompression=TextureImporterCompression.Uncompressed;im.mipmapEnabled=false;var s=new SpriteMetaData[count];for(int i=0;i<count;i++)s[i]=new SpriteMetaData{name=$"{prefix}_{i:000}",rect=new Rect(i*width,0,width,height),alignment=(int)SpriteAlignment.Center,pivot=new(.5f,.5f)};
#pragma warning disable CS0618
 im.spritesheet=s;
#pragma warning restore CS0618
 im.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().OrderBy(x=>x.name,StringComparer.Ordinal).ToArray();}
 static GameObject Build(Sprite[] f,Sprite[] v){var root=new GameObject("DeepTide Colossus",typeof(SpriteRenderer),typeof(Rigidbody2D),typeof(CircleCollider2D),typeof(DeepTideColossusEnemy));var sr=root.GetComponent<SpriteRenderer>();sr.sprite=f[0];sr.sortingOrder=22;var rb=root.GetComponent<Rigidbody2D>();rb.gravityScale=0;rb.linearDamping=10;rb.freezeRotation=true;var c=root.GetComponent<CircleCollider2D>();c.radius=.38f;c.isTrigger=true;var so=new SerializedObject(root.GetComponent<DeepTideColossusEnemy>());Assign(so.FindProperty("frames"),f);Assign(so.FindProperty("effectFrames"),v);so.ApplyModifiedPropertiesWithoutUndo();var prefab=PrefabUtility.SaveAsPrefabAsset(root,"Assets/Prefabs/DeepTideColossus.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static void Assign(SerializedProperty property,Sprite[] sprites){property.arraySize=sprites.Length;for(int i=0;i<sprites.Length;i++)property.GetArrayElementAtIndex(i).objectReferenceValue=sprites[i];}
}
